  "track.cleancode.vz.td.walk.none": "chưa có test nào chạy",
  "track.cleancode.vz.td.walk.code": "viết mã, chưa có test",
  "track.cleancode.vz.td.walk.prod": "không có test: lỗi lộ ra ở bệnh nhân",
